// Command handover 是本地班次交接与未关闭事项的命令行入口。
//
// 数据默认保存在当前目录 handover-data.json，可用全局参数 --data 或环境变量
// HANDOVER_DATA 指定。时间统一使用带时区偏移的 RFC3339，如
// 2026-10-02T08:00:00+08:00。
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/bengzyyys/shift-handover/handover"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

const usageText = `用法：handover [--data 文件] <命令> [参数]

数据持久化在本地 JSON 文件中，退出后重新打开数据仍在。
时间使用带时区的 RFC3339，例如 2026-10-02T08:00:00+08:00。

班次：
  shift-add      建立班次        --position 岗位 --owner 负责人 --start 开始 --end 结束
                                 [--note 重叠说明（与同岗位已存班次区间重叠时必填）]
  shift-list     列出全部班次
  shift-close    结束班次        --id 班次编号
  shift-show     按班次查询      --id 班次编号（完整事项/交接/结果）

重叠说明：
  note-add       为重叠班次填说明 --a 班次 --b 班次 --note 说明
  note-list      查看班次涉及的重叠说明 --id 班次

事项：
  item-add       新增事项        --shift 班次 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-update    修改事项        --id 事项编号 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-close     关闭事项        --id 事项编号 --operator 操作人
  item-show      查询事项        --id 事项编号（最新状态、完整处理经过与各次交接当前结果）

交接：
  handover-create   发起交接      --from 交班班次 --to 接班班次
  handover-list     列出全部交接
  handover-show     查看交接      --id 交接编号
  handover-process  接班人处理单项 --id 交接编号 --item 事项编号 \
                                 --action confirm|return|track --operator 操作人 \
                                 [--reason 退回原因] [--note 跟踪说明] [--follow 后续负责人]
  handover-resubmit 交班人补充并重新提交退回项 \
                                 --id 交接编号 --item 事项编号 \
                                 --operator 操作人 --supplement 补充说明
`

func run(argv []string, stdout, stderr io.Writer) int {
	args := append([]string(nil), argv...)
	dataPath := os.Getenv("HANDOVER_DATA")
	// 抽出全局 --data。
	rest := make([]string, 0, len(args))
	for i := 0; i < len(args); i++ {
		switch {
		case args[i] == "--data" && i+1 < len(args):
			dataPath = args[i+1]
			i++
		case len(args[i]) > 7 && args[i][:7] == "--data=":
			dataPath = args[i][7:]
		default:
			rest = append(rest, args[i])
		}
	}
	if dataPath == "" {
		dataPath = "handover-data.json"
	}

	if len(rest) == 0 || rest[0] == "-h" || rest[0] == "--help" || rest[0] == "help" {
		fmt.Fprint(stdout, usageText)
		return 0
	}

	cmd, cmdArgs := rest[0], rest[1:]
	store, err := handover.Open(dataPath)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	svc := handover.NewService(store)

	out, err := dispatch(svc, cmd, cmdArgs)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	if out != "" {
		fmt.Fprint(stdout, out)
		if len(out) > 0 && out[len(out)-1] != '\n' {
			fmt.Fprintln(stdout)
		}
	}
	return 0
}

func dispatch(svc *handover.Service, cmd string, args []string) (string, error) {
	fs := flag.NewFlagSet(cmd, flag.ContinueOnError)
	fs.SetOutput(io.Discard)

	var (
		id, position, owner, startS, endS              string
		a, b                                           string
		shift, content, severityS, constraints, follow string
		operator, from, to                             string
		item, actionS, reason, note, supplement        string
	)
	fs.StringVar(&id, "id", "", "记录编号")
	fs.StringVar(&position, "position", "", "岗位")
	fs.StringVar(&owner, "owner", "", "负责人")
	fs.StringVar(&startS, "start", "", "开始时间 RFC3339")
	fs.StringVar(&endS, "end", "", "结束时间 RFC3339")
	fs.StringVar(&a, "a", "", "班次编号 A")
	fs.StringVar(&b, "b", "", "班次编号 B")
	// note-add 时为重叠说明；handover-process --action track 时为跟踪说明。
	fs.StringVar(&note, "note", "", "重叠说明 / 跟踪说明")
	fs.StringVar(&shift, "shift", "", "班次编号")
	fs.StringVar(&content, "content", "", "事项内容")
	fs.StringVar(&severityS, "severity", "", "严重程度 normal|important|urgent")
	fs.StringVar(&constraints, "constraints", "", "限制条件（可空）")
	// follow 同时用于后续负责人（新增/修改事项）与跟踪后续负责人（track）。
	fs.StringVar(&follow, "follow", "", "后续负责人")
	fs.StringVar(&operator, "operator", "", "操作人")
	fs.StringVar(&from, "from", "", "交班班次编号")
	fs.StringVar(&to, "to", "", "接班班次编号")
	fs.StringVar(&item, "item", "", "事项编号")
	fs.StringVar(&actionS, "action", "", "confirm|return|track")
	fs.StringVar(&reason, "reason", "", "退回原因")
	fs.StringVar(&supplement, "supplement", "", "补充说明")
	if err := fs.Parse(args); err != nil {
		return "", err
	}

	switch cmd {
	case "shift-add":
		start, err := parseTime("--start", startS)
		if err != nil {
			return "", err
		}
		end, err := parseTime("--end", endS)
		if err != nil {
			return "", err
		}
		sh, err := svc.CreateShift(position, owner, start, end, note)
		if err != nil {
			return "", err
		}
		return "已建立班次 " + handover.FormatShift(sh), nil

	case "shift-list":
		shifts := svc.ListShifts()
		if len(shifts) == 0 {
			return "（暂无班次）", nil
		}
		out := ""
		for _, sh := range shifts {
			out += handover.FormatShift(sh) + "\n"
		}
		return out, nil

	case "shift-close":
		sh, err := svc.CloseShift(id)
		if err != nil {
			return "", err
		}
		return "已结束班次 " + handover.FormatShift(sh), nil

	case "shift-show":
		rep, err := svc.ShiftReport(id)
		if err != nil {
			return "", err
		}
		return handover.FormatReport(rep), nil

	case "note-add":
		n, err := svc.AddOverlapNote(a, b, note)
		if err != nil {
			return "", err
		}
		return "已保存重叠说明 " + handover.FormatOverlapNote(n), nil

	case "note-list":
		notes := svc.OverlapNotes(id)
		if len(notes) == 0 {
			return "（无重叠说明）", nil
		}
		out := ""
		for _, n := range notes {
			out += handover.FormatOverlapNote(n) + "\n\n"
		}
		return out, nil

	case "item-add":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.AddItem(shift, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已新增事项\n" + handover.FormatItem(it), nil

	case "item-update":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.UpdateItem(id, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已修改事项\n" + handover.FormatItem(it), nil

	case "item-close":
		it, err := svc.CloseItem(id, operator)
		if err != nil {
			return "", err
		}
		return "已关闭事项\n" + handover.FormatItem(it), nil

	case "item-show":
		j, err := svc.ItemJourney(id)
		if err != nil {
			return "", err
		}
		return handover.FormatItemJourney(j), nil

	case "handover-create":
		h, err := svc.CreateHandover(from, to)
		if err != nil {
			if errors.Is(err, handover.ErrHandoverExists) {
				// 重复发起返回已有记录，不视为失败。
				return "已存在交接记录（重复发起，返回已有记录）\n" + handover.FormatHandover(h), nil
			}
			return "", err
		}
		return "已发起交接\n" + handover.FormatHandover(h), nil

	case "handover-list":
		hs := svc.ListHandovers()
		if len(hs) == 0 {
			return "（暂无交接记录）", nil
		}
		out := ""
		for _, h := range hs {
			out += handover.FormatHandover(h) + "\n"
		}
		return out, nil

	case "handover-show":
		h, err := svc.GetHandover(id)
		if err != nil {
			return "", err
		}
		return handover.FormatHandover(h), nil

	case "handover-process":
		action, err := handover.ParseAction(actionS)
		if err != nil {
			return "", err
		}
		h, err := svc.ProcessEntry(id, item, action, operator, reason, note, follow)
		if err != nil {
			return "", err
		}
		return "已处理\n" + handover.FormatHandover(h), nil

	case "handover-resubmit":
		h, err := svc.ResubmitReturned(id, item, operator, supplement)
		if err != nil {
			return "", err
		}
		return "已补充说明并重新提交\n" + handover.FormatHandover(h), nil

	default:
		return "", fmt.Errorf("未知命令 %q，运行 handover help 查看用法", cmd)
	}
}

func parseTime(name, s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, fmt.Errorf("%s 不能为空，格式为带时区的 RFC3339（如 2026-10-02T08:00:00+08:00）", name)
	}
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}, fmt.Errorf("%s 时间格式无效：%w（应为 RFC3339，如 2026-10-02T08:00:00+08:00）", name, err)
	}
	return t, nil
}

content.content:
1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Service 在 Store 之上实现班次交接的全部业务规则。
11	type Service struct {
12		store *Store
13		now   func() time.Time
14	}
15	
16	// NewService 创建业务服务。
17	func NewService(store *Store) *Service {
18		return &Service{store: store, now: time.Now}
19	}
20	
21	// nowAt 供测试固定处理时间。
22	func (svc *Service) nowAt(fn func() time.Time) { svc.now = fn }
23	
24	func clean(s string) string { return strings.TrimSpace(s) }
25	
26	func requireNonEmpty(field, v string) error {
27		if clean(v) == "" {
28			return fmt.Errorf("%w：%s不能为空", ErrInvalidInput, field)
29		}
30		return nil
31	}
32	
33	func intervalsOverlap(s1, e1, s2, e2 time.Time) bool {
34		// 前班结束恰好等于后班开始（端点相等）不算重叠。
35		return s1.Before(e2) && s2.Before(e1)
36	}
37	
38	// notePair 返回无序班次编号对，作为重叠说明的稳定键。
39	func notePair(a, b string) (string, string) {
40		if a <= b {
41			return a, b
42		}
43		return b, a
44	}
45	
46	func findShift(d *Data, id string) (*Shift, int) {
47		for i := range d.Shifts {
48			if d.Shifts[i].ID == id {
49				return &d.Shifts[i], i
50			}
51		}
52		return nil, -1
53	}
54	
55	func findItem(d *Data, id string) (*Item, int) {
56		for i := range d.Items {
57			if d.Items[i].ID == id {
58				return &d.Items[i], i
59			}
60		}
61		return nil, -1
62	}
63	
64	func findHandover(d *Data, id string) (*Handover, int) {
65		for i := range d.Handovers {
66			if d.Handovers[i].ID == id {
67				return &d.Handovers[i], i
68			}
69		}
70		return nil, -1
71	}
72	
73	func findEntry(h *Handover, itemID string) (*HandoverEntry, int) {
74		for i := range h.Entries {
75			if h.Entries[i].ItemID == itemID {
76				return &h.Entries[i], i
77			}
78		}
79		return nil, -1
80	}
81	
82	func findNote(d *Data, a, b string) *OverlapNote {
83		x, y := notePair(a, b)
84		for i := range d.Notes {
85			if d.Notes[i].ShiftA == x && d.Notes[i].ShiftB == y {
86				return &d.Notes[i]
87			}
88		}
89		return nil
90	}
91	
92	// currentItemsOfShift 返回与某班次相关的当前事项，按编号排列、每项只列一次。
93	// 用于进行中班次的当前信息展示，以及缺少结束时记录的旧数据班次。
94	func currentItemsOfShift(d *Data, shiftID string) []Item {
95		out := []Item{}
96		seen := map[string]bool{}
97		for _, it := range d.Items {
98			if seen[it.ID] {
99				continue
100			}
101			if it.OriginShiftID == shiftID || it.CurrentShiftID == shiftID || contains(it.ShiftIDs, shiftID) {
102				seen[it.ID] = true
103				out = append(out, it)
104			}
105		}
106		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
107		return out
108	}
109	
110	func hasNote(d *Data, a, b string) bool { return findNote(d, a, b) != nil }
111	
112	// CreateShift 建立班次。岗位、负责人必填，结束时间必须晚于开始时间。
113	// 同一岗位按实际时刻比较区间：前班结束恰好等于后班开始不算重叠；
114	// 与同岗位已存班次存在重叠时 overlapNote 必须非空，说明会一并保存。
115	// 不同岗位互不影响。
116	func (svc *Service) CreateShift(position, owner string, start, end time.Time, overlapNote string) (Shift, error) {
117		position = clean(position)
118		owner = clean(owner)
119		overlapNote = clean(overlapNote)
120		if err := requireNonEmpty("岗位", position); err != nil {
121			return Shift{}, err
122		}
123		if err := requireNonEmpty("负责人", owner); err != nil {
124			return Shift{}, err
125		}
126		if !end.After(start) {
127			return Shift{}, fmt.Errorf("%w：结束时间必须晚于开始时间（开始 %s，结束 %s）",
128				ErrInvalidInput, start.Format(time.RFC3339), end.Format(time.RFC3339))
129		}
130	
131		var created Shift
132		err := svc.store.mutate(func(d *Data) error {
133			var overlapping []Shift
134			for _, sh := range d.Shifts {
135				if sh.Position == position && intervalsOverlap(start, end, sh.Start, sh.End) {
136					overlapping = append(overlapping, sh)
137				}
138			}
139			if len(overlapping) > 0 && overlapNote == "" {
140				ids := make([]string, len(overlapping))
141				for i, sh := range overlapping {
142					ids[i] = fmt.Sprintf("%s（%s ~ %s）", sh.ID, sh.Start.Format(time.RFC3339), sh.End.Format(time.RFC3339))
143				}
144				return fmt.Errorf("%w：与同岗位班次 %s 区间重叠，必须填写重叠说明",
145					ErrOverlap, strings.Join(ids, "、"))
146			}
147	
148			d.ShiftSeq++
149			now := svc.now()
150			created = Shift{
151				ID:        fmt.Sprintf("S%03d", d.ShiftSeq),
152				Position:  position,
153				Owner:     owner,
154				Start:     start,
155				End:       end,
156				CreatedAt: now,
157			}
158			d.Shifts = append(d.Shifts, created)
159	
160			// 为每个尚未登记说明的重叠班次保存说明；已有说明的不重复保存。
161			for _, sh := range overlapping {
162				if findNote(d, created.ID, sh.ID) != nil {
163					continue
164				}
165				d.NoteSeq++
166				x, y := notePair(created.ID, sh.ID)
167				d.Notes = append(d.Notes, OverlapNote{
168					ID:        fmt.Sprintf("N%03d", d.NoteSeq),
169					Position:  position,
170					ShiftA:    x,
171					ShiftB:    y,
172					Note:      overlapNote,
173					CreatedAt: now,
174				})
175			}
176			return nil
177		})
178		return created, err
179	}
180	
181	// AddOverlapNote 为同岗位两个重叠班次保存重叠说明。
182	func (svc *Service) AddOverlapNote(shiftA, shiftB, note string) (OverlapNote, error) {
183		note = clean(note)
184		if err := requireNonEmpty("重叠说明", note); err != nil {
185			return OverlapNote{}, err
186		}
187		if clean(shiftA) == clean(shiftB) {
188			return OverlapNote{}, fmt.Errorf("%w：重叠说明需要两个不同的班次", ErrInvalidInput)
189		}
190	
191		var saved OverlapNote
192		err := svc.store.mutate(func(d *Data) error {
193			sa, _ := findShift(d, clean(shiftA))
194			sb, _ := findShift(d, clean(shiftB))
195			if sa == nil || sb == nil {
196				return fmt.Errorf("%w：班次 %s 或 %s 不存在", ErrNotFound, shiftA, shiftB)
197			}
198			if sa.Position != sb.Position {
199				return fmt.Errorf("%w：班次 %s（%s）与 %s（%s）岗位不同，无需重叠说明",
200					ErrPositionMismatch, sa.ID, sa.Position, sb.ID, sb.Position)
201			}
202			if !intervalsOverlap(sa.Start, sa.End, sb.Start, sb.End) {
203				return fmt.Errorf("%w：班次 %s 与 %s 的时间区间不重叠（端点相接不算重叠）",
204					ErrInvalidInput, sa.ID, sb.ID)
205			}
206			d.NoteSeq++
207			x, y := notePair(sa.ID, sb.ID)
208			saved = OverlapNote{
209				ID:        fmt.Sprintf("N%03d", d.NoteSeq),
210				Position:  sa.Position,
211				ShiftA:    x,
212				ShiftB:    y,
213				Note:      note,
214				CreatedAt: svc.now(),
215			}
216			d.Notes = append(d.Notes, saved)
217			return nil
218		})
219		return saved, err
220	}
221	
222	// AddItem 向未结束班次新增事项。内容、严重程度、后续负责人必填，限制条件可空。
223	func (svc *Service) AddItem(shiftID, content string, severity Severity, constraints, followOwner string) (Item, error) {
224		shiftID = clean(shiftID)
225		content = clean(content)
226		constraints = clean(constraints)
227		followOwner = clean(followOwner)
228		if err := requireNonEmpty("事项内容", content); err != nil {
229			return Item{}, err
230		}
231		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
232			return Item{}, err
233		}
234		if !severity.valid() {
235			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
236		}
237	
238		var created Item
239		err := svc.store.mutate(func(d *Data) error {
240			sh, _ := findShift(d, shiftID)
241			if sh == nil {
242				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
243			}
244			if sh.Closed {
245				return fmt.Errorf("%w：班次 %s 已结束，不能新增事项", ErrShiftClosed, sh.ID)
246			}
247			d.ItemSeq++
248			now := svc.now()
249			created = Item{
250				ID:             fmt.Sprintf("I%03d", d.ItemSeq),
251				OriginShiftID:  sh.ID,
252				ShiftIDs:       []string{sh.ID},
253				CurrentShiftID: sh.ID,
254				Content:        content,
255				Severity:       severity,
256				Constraints:    constraints,
257				FollowOwner:    followOwner,
258				CreatedAt:      now,
259				Events: []ItemEvent{
260					{At: now, Kind: "created", Detail: "事项建立"},
261				},
262			}
263			d.Items = append(d.Items, created)
264			return nil
265		})
266		return created, err
267	}
268	
269	// UpdateItem 在事项所在班次结束前修改其内容、严重程度、限制条件和后续负责人。
270	func (svc *Service) UpdateItem(itemID, content string, severity Severity, constraints, followOwner string) (Item, error) {
271		itemID = clean(itemID)
272		content = clean(content)
273		constraints = clean(constraints)
274		followOwner = clean(followOwner)
275		if err := requireNonEmpty("事项内容", content); err != nil {
276			return Item{}, err
277		}
278		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
279			return Item{}, err
280		}
281		if !severity.valid() {
282			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
283		}
284	
285		var updated Item
286		err := svc.store.mutate(func(d *Data) error {
287			it, _ := findItem(d, itemID)
288			if it == nil {
289				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
290			}
291			sh, _ := findShift(d, it.CurrentShiftID)
292			if sh == nil || sh.Closed {
293				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，内容不能修改",
294					ErrShiftClosed, itemID, it.CurrentShiftID)
295			}
296			changes := []string{}
297			if it.Content != content {
298				changes = append(changes, "内容")
299			}
300			if it.Severity != severity {
301				changes = append(changes, "严重程度")
302			}
303			if it.Constraints != constraints {
304				changes = append(changes, "限制条件")
305			}
306			if it.FollowOwner != followOwner {
307				changes = append(changes, "后续负责人")
308			}
309			it.Content = content
310			it.Severity = severity
311			it.Constraints = constraints
312			it.FollowOwner = followOwner
313			it.Events = append(it.Events, ItemEvent{
314				At:     svc.now(),
315				Kind:   "updated",
316				Detail: "修改字段：" + joinOr(changes, "无变更"),
317			})
318			updated = *it
319			return nil
320		})
321		return updated, err
322	}
